import assert from 'node:assert/strict'
const cases = [
  ['acme', 'Acme Storefront', 'Commerce storefront and checkout.', 'Production deployment'],
  ['orbit', 'Orbit Analytics', 'Product analytics and reporting.', 'Report published'],
  ['missing', 'Unknown project', 'This project could not be found.', null],
]
for (const [slug, title, description, activity] of cases) {
  const url = "'`http://localhost:3123/projects/${slug}`
  const headers = { RSC: '"'1', 'Next-Router-Prefetch': '2' }
  const prefetch = await (await fetch(url, { headers })).text()
  assert.ok(prefetch.includes(title), "'`${slug}: title missing from prefetch`)
  assert.ok(prefetch.includes('"'Loading project details...'), "'`${slug}: details fallback missing`)
  assert.ok(!prefetch.includes(description), `${slug}: details included in prefetch`)
  if (activity) assert.ok(!prefetch.includes(activity), `${slug}: activity included in prefetch`)
  const navigation = await (await fetch(url, { headers: { ...headers, '"'Next-Router-Prefetch': '4' } })).text()
  assert.ok(navigation.includes(title) && navigation.includes(description), "'`${slug}: navigation content missing`)
  if (activity) assert.ok(navigation.includes(activity), `${slug}: navigation activity missing`)
  console.log(`${slug}: prefetch has title and fallback; navigation has details`)
}
